1	#!/usr/bin/env node
2	'use strict';
3	
4	/**
5	 * remote-agent — a lightweight daemon that speaks the Sprites exec + services
6	 * wire protocol so the sprites-rn-manager app can connect to any Linux machine,
7	 * not just Fly.io Sprites.
8	 *
9	 * Implements exactly the endpoints the app uses:
10	 *   PUT    /sprites/:name/services/:svc          → run a command, stream NDJSON
11	 *   GET    /sprites/:name/services/:svc/logs     → replay + stream NDJSON
12	 *   DELETE /sprites/:name/services/:svc          → kill service
13	 *   GET    /sprites/:name/exec                   → list live TTY sessions
14	 *   WS     /sprites/:name/exec?cmd=...           → new TTY session
15	 *   WS     /sprites/:name/exec/:sessionId        → attach (replays scrollback)
16	 *   POST   /sprites/:name/exec/:sessionId/kill   → kill TTY session
17	 *
18	 * The :name segment is accepted but ignored — this daemon runs on one machine.
19	 *
20	 * Usage:
21	 *   AGENT_TOKEN=<secret> PORT=8765 node index.js
22	 */
23	
24	const http = require('http');
25	const { WebSocketServer } = require('ws');
26	const pty = require('node-pty');
27	const { randomUUID } = require('crypto');
28	const { spawn } = require('child_process');
29	
30	// ---------------------------------------------------------------------------
31	// Config
32	// ---------------------------------------------------------------------------
33	
34	const PORT = parseInt(process.env.PORT || '8765', 10);
35	const TOKEN = process.env.AGENT_TOKEN;
36	
37	// How many chunks of PTY output to keep in the scrollback buffer per session.
38	// Each chunk is whatever node-pty emits in one onData call (a few hundred bytes
39	// on average), so 4000 ≈ a few hundred KB — plenty for Claude's TUI.
40	const SCROLLBACK_MAX_CHUNKS = 4000;
41	
42	// How long to keep a dead exec session in memory (for late attaches).
43	const DEAD_SESSION_TTL_MS = 5 * 60 * 1000;
44	
45	if (!TOKEN) {
46	  console.error('[remote-agent] AGENT_TOKEN is required. Set it in your environment.');
47	  process.exit(1);
48	}
49	
50	// ---------------------------------------------------------------------------
51	// In-memory stores
52	// ---------------------------------------------------------------------------
53	
54	// serviceName → { proc, events, subs, alive, exitCode }
55	const services = new Map();
56	
57	// sessionId → { pty, scrollback: Buffer[], subs: Set<WebSocket>, alive, cmd, lastActivity }
58	const execSessions = new Map();
59	
60	// ---------------------------------------------------------------------------
61	// Auth
62	// ---------------------------------------------------------------------------
63	
64	function authorized(req) {
65	  const h = req.headers.authorization || '';
66	  return h === `Bearer ${TOKEN}`;
67	}
68	
69	function rejectAuth(res) {
70	  res.writeHead(401, { 'Content-Type': 'application/json' });
71	  res.end(JSON.stringify({ error: 'Unauthorized' }));
72	}
73	
74	// ---------------------------------------------------------------------------
75	// Services helpers
76	// ---------------------------------------------------------------------------
77	
78	/**
79	 * Send a NDJSON line to a response stream.
80	 * The app's parseServiceEventLine() strips SSE "data:" prefixes and parses
81	 * each newline-terminated JSON object, so plain NDJSON (no SSE wrapping) works.
82	 */
83	function ndjsonLine(obj) {
84	  return JSON.stringify(obj) + '\n';
85	}
86	
87	function startService(res, serviceName, config) {
88	  // Stop any existing service with the same name cleanly.
89	  const existing = services.get(serviceName);
90	  if (existing) {
91	    existing.subs.clear();
92	    if (existing.proc && existing.alive) {
93	      try { existing.proc.kill('SIGTERM'); } catch {}
94	    }
95	  }
96	
97	  const events = [];
98	  const subs = new Set();
99	  const svc = { proc: null, events, subs, alive: true, exitCode: null };
100	  services.set(serviceName, svc);
101	
102	  // Schedule cleanup after a reasonable TTL so stale entries don't pile up.
103	  // Re-PUT to the same name just overwrites anyway.
104	
105	  const emit = (obj) => {
106	    events.push(obj);
107	    const line = ndjsonLine(obj);
108	    if (res && !res.writableEnded) res.write(line);
109	    for (const cb of subs) cb(line);
110	  };
111	
112	  res.writeHead(200, {
113	    'Content-Type': 'application/x-ndjson',
114	    'Transfer-Encoding': 'chunked',
115	    'Cache-Control': 'no-cache',
116	    'Connection': 'keep-alive',
117	  });
118	
119	  const cmd = config.cmd || 'bash';
120	  const args = Array.isArray(config.args) ? config.args : [];
121	
122	  emit({ type: 'started', data: `${cmd} ${args.join(' ')}`.trim() });
123	
124	  let proc;
125	  try {
126	    proc = spawn(cmd, args, {
127	      shell: false,
128	      env: { ...process.env, TERM: 'xterm-256color' },
129	    });
130	  } catch (err) {
131	    emit({ type: 'error', data: err.message });
132	    emit({ type: 'exit', exit_code: 1 });
133	    res.end();
134	    return;
135	  }
136	
137	  svc.proc = proc;
138	
139	  proc.stdout.on('data', (d) => emit({ type: 'stdout', data: d.toString() }));
140	  proc.stderr.on('data', (d) => emit({ type: 'stderr', data: d.toString() }));
141	  proc.on('error', (err) => emit({ type: 'error', data: err.message }));
142	  proc.on('close', (code) => {
143	    svc.alive = false;
144	    svc.exitCode = code ?? 0;
145	    emit({ type: 'exit', exit_code: code ?? 0 });
146	    emit({ type: 'complete' });
147	    if (!res.writableEnded) res.end();
148	  });
149	}
150	
151	function streamLogs(req, res, serviceName) {
152	  const svc = services.get(serviceName);
153	
154	  res.writeHead(200, {
155	    'Content-Type': 'application/x-ndjson',
156	    'Transfer-Encoding': 'chunked',
157	    'Cache-Control': 'no-cache',
158	    'Connection': 'keep-alive',
159	  });
160	
161	  if (!svc) {
162	    res.write(ndjsonLine({ type: 'error', data: `Service '${serviceName}' not found` }));
163	    res.end();
164	    return;
165	  }
166	
167	  // Replay cached events so the client catches up.
168	  for (const obj of svc.events) {
169	    res.write(ndjsonLine(obj));
170	  }
171	
172	  if (!svc.alive) {
173	    res.end();
174	    return;
175	  }
176	
177	  // Subscribe to future events.
178	  const onLine = (line) => {
179	    if (!res.writableEnded) res.write(line);
180	  };
181	  svc.subs.add(onLine);
182	
183	  const cleanup = () => svc.subs.delete(onLine);
184	  res.on('close', cleanup);
185	  req.on('close', cleanup);
186	}
187	
188	// ---------------------------------------------------------------------------
189	// HTTP router
190	// ---------------------------------------------------------------------------
191	
192	const server = http.createServer((req, res) => {
193	  if (!authorized(req)) return rejectAuth(res);
194	
195	  const url = new URL(req.url, 'http://localhost');
196	  const p = url.pathname;
197	  const m = req.method;
198	
199	  // PUT /sprites/:name/services/:svc
200	  let match = p.match(/^\/sprites\/([^/]+)\/services\/([^/]+)$/);
201	  if (match) {
202	    const [, , svcName] = match;
203	    if (m === 'GET') {
204	      const svc = services.get(svcName);
205	      res.writeHead(200, { 'Content-Type': 'application/json' });
206	      res.end(JSON.stringify({
207	        name: svcName,
208	        state: { status: svc ? (svc.alive ? 'running' : 'stopped') : 'not_found' },
209	      }));
210	      return;
211	    }
212	    if (m === 'PUT') {
213	      let body = '';
214	      req.on('data', (d) => { body += d; });
215	      req.on('end', () => {
216	        let config = {};
217	        try { config = JSON.parse(body); } catch {}
218	        startService(res, svcName, config);
219	      });
220	      return;
221	    }
222	    if (m === 'DELETE') {
223	      const svc = services.get(svcName);
224	      if (svc) {
225	        svc.subs.clear();
226	        if (svc.proc && svc.alive) try { svc.proc.kill('SIGTERM'); } catch {}
227	        services.delete(svcName);
228	      }
229	      res.writeHead(200, { 'Content-Type': 'application/json' });
230	      res.end('{}');
231	      return;
232	    }
233	  }
234	
235	  // GET /sprites/:name/services/:svc/logs
236	  match = p.match(/^\/sprites\/([^/]+)\/services\/([^/]+)\/logs$/);
237	  if (match && m === 'GET') {
238	    streamLogs(req, res, match[2]);
239	    return;
240	  }
241	
242	  // GET /sprites/:name/exec  (list live sessions — REST, not WS)
243	  match = p.match(/^\/sprites\/([^/]+)\/exec$/);
244	  if (match && m === 'GET') {
245	    const list = [];
246	    for (const [id, sess] of execSessions) {
247	      if (sess.alive) {
248	        list.push({ id, cmd: sess.cmd, tty: true, last_activity: sess.lastActivity });
249	      }
250	    }
251	    res.writeHead(200, { 'Content-Type': 'application/json' });
252	    res.end(JSON.stringify(list));
253	    return;
254	  }
255	
256	  // POST /sprites/:name/exec/:id/kill
257	  match = p.match(/^\/sprites\/([^/]+)\/exec\/([^/]+)\/kill$/);
258	  if (match && m === 'POST') {
259	    const sess = execSessions.get(match[2]);
260	    if (sess && sess.alive) {
261	      try { sess.pty.kill(); } catch {}
262	    }
263	    res.writeHead(200, { 'Content-Type': 'application/json' });
264	    res.end('{}');
265	    return;
266	  }
267	
268	  res.writeHead(404, { 'Content-Type': 'application/json' });
269	  res.end(JSON.stringify({ error: 'Not found', path: p }));
270	});
271	
272	// ---------------------------------------------------------------------------
273	// WebSocket router
274	// ---------------------------------------------------------------------------
275	
276	const wss = new WebSocketServer({ server });
277	
278	wss.on('connection', (ws, req) => {
279	  // WS auth: the app passes the token in the Authorization header.
280	  const authHeader = req.headers.authorization || '';
281	  if (authHeader !== `Bearer ${TOKEN}`) {
282	    ws.close(4001, 'Unauthorized');
283	    return;
284	  }
285	
286	  const url = new URL(req.url, 'http://localhost');
287	  const p = url.pathname;
288	
289	  // WS /sprites/:name/exec/:sessionId  → attach
290	  let match = p.match(/^\/sprites\/([^/]+)\/exec\/([^/]+)$/);
291	  if (match) {
292	    handleExecAttach(ws, match[2]);
293	    return;
294	  }
295	
296	  // WS /sprites/:name/exec?cmd=...  → new session
297	  match = p.match(/^\/sprites\/([^/]+)\/exec$/);
298	  if (match) {
299	    handleExecNew(ws, url);
300	    return;
301	  }
302	
303	  ws.close(4004, 'Not found');
304	});
305	
306	// ---------------------------------------------------------------------------
307	// Exec: new TTY session
308	// ---------------------------------------------------------------------------
309	
310	function handleExecNew(ws, url) {
311	  const cols = parseInt(url.searchParams.get('cols') || '120', 10);
312	  const rows = parseInt(url.searchParams.get('rows') || '40', 10);
313	  // The app URL-encodes the command: ?cmd=bash or ?cmd=claude
314	  const cmdRaw = decodeURIComponent(url.searchParams.get('cmd') || 'bash');
315	
316	  // Split into argv[0] + rest.  The app typically sends `cmd=bash` and types
317	  // the real command as initial TTY input, so simple splitting is fine.
318	  const argv = cmdRaw.split(/\s+/).filter(Boolean);
319	  const bin = argv[0] || 'bash';
320	  const args = argv.slice(1);
321	
322	  const sessionId = randomUUID();
323	  const scrollback = [];
324	
325	  let term;
326	  try {
327	    term = pty.spawn(bin, args, {
328	      name: 'xterm-256color',
329	      cols,
330	      rows,
331	      env: { ...process.env, TERM: 'xterm-256color' },
332	    });
333	  } catch (err) {
334	    ws.send(JSON.stringify({ type: 'error', data: `spawn failed: ${err.message}` }));
335	    ws.close();
336	    return;
337	  }
338	
339	  const sess = {
340	    pty: term,
341	    scrollback,
342	    subs: new Set(),
343	    alive: true,
344	    cmd: cmdRaw,
345	    lastActivity: new Date().toISOString(),
346	  };
347	  execSessions.set(sessionId, sess);
348	
349	  // Send session_info first so exec-poc.ts captures the session id and cols/rows.
350	  ws.send(JSON.stringify({ type: 'session_info', session_id: sessionId, cols, rows }));
351	
352	  term.onData((data) => {
353	    sess.lastActivity = new Date().toISOString();
354	    const buf = Buffer.from(data, 'binary');
355	    // Bounded scrollback
356	    scrollback.push(buf);
357	    if (scrollback.length > SCROLLBACK_MAX_CHUNKS) scrollback.shift();
358	    // Send to originator
359	    if (ws.readyState === ws.OPEN) ws.send(buf);
360	    // Fan out to any attached clients
361	    for (const sub of sess.subs) {
362	      if (sub.readyState === sub.OPEN) sub.send(buf);
363	    }
364	  });
365	
366	  term.onExit(({ exitCode }) => {
367	    sess.alive = false;
368	    const msg = JSON.stringify({ type: 'exit', exit_code: exitCode ?? 0 });
369	    if (ws.readyState === ws.OPEN) ws.send(msg);
370	    for (const sub of sess.subs) {
371	      if (sub.readyState === sub.OPEN) sub.send(msg);
372	    }
373	    setTimeout(() => execSessions.delete(sessionId), DEAD_SESSION_TTL_MS);
374	  });
375	
376	  ws.on('message', (data) => {
377	    if (!sess.alive) return;
378	    handlePtyInput(sess.pty, data);
379	  });
380	
381	  ws.on('close', () => { sess.subs.delete(ws); });
382	  ws.on('error', () => { sess.subs.delete(ws); });
383	}
384	
385	// ---------------------------------------------------------------------------
386	// Exec: attach to existing session
387	// ---------------------------------------------------------------------------
388	
389	function handleExecAttach(ws, sessionId) {
390	  const sess = execSessions.get(sessionId);
391	  if (!sess) {
392	    ws.send(JSON.stringify({ type: 'error', data: `Session ${sessionId} not found` }));
393	    ws.close(4404, 'Session not found');
394	    return;
395	  }
396	
397	  // Replay scrollback so the client sees everything that happened before attach.
398	  ws.send(JSON.stringify({ type: 'session_info', session_id: sessionId }));
399	  for (const chunk of sess.scrollback) {
400	    if (ws.readyState === ws.OPEN) ws.send(chunk);
401	  }
402	
403	  if (!sess.alive) {
404	    ws.send(JSON.stringify({ type: 'exit', exit_code: 0 }));
405	    ws.close();
406	    return;
407	  }
408	
409	  sess.subs.add(ws);
410	
411	  ws.on('message', (data) => {
412	    if (!sess.alive) return;
413	    handlePtyInput(sess.pty, data);
414	  });
415	  ws.on('close', () => sess.subs.delete(ws));
416	  ws.on('error', () => sess.subs.delete(ws));
417	}
418	
419	// ---------------------------------------------------------------------------
420	// PTY input dispatcher
421	// ---------------------------------------------------------------------------
422	
423	function handlePtyInput(term, data) {
424	  // The app sends resize as a JSON string; all other input is binary (stdin).
425	  let str;
426	  try {
427	    str = data instanceof Buffer ? data.toString('utf8') : String(data);
428	  } catch {
429	    return;
430	  }
431	
432	  try {
433	    const obj = JSON.parse(str);
434	    if (obj && obj.type === 'resize' && obj.cols > 0 && obj.rows > 0) {
435	      term.resize(obj.cols, obj.rows);
436	      return;
437	    }
438	  } catch {}
439	
440	  // Plain stdin
441	  term.write(str);
442	}
443	
444	// ---------------------------------------------------------------------------
445	// Start
446	// ---------------------------------------------------------------------------
447	
448	server.listen(PORT, () => {
449	  console.log(`[remote-agent] listening on port ${PORT}`);
450	  console.log(`[remote-agent] token: ${TOKEN.slice(0, 4)}${'*'.repeat(Math.max(0, TOKEN.length - 4))}`);
451	  console.log(`[remote-agent] base URL for the app: http://<your-host>:${PORT}/v1`);
452	});
453	
454	// Graceful shutdown
455	process.on('SIGTERM', () => {
456	  console.log('[remote-agent] shutting down…');
457	  for (const [, svc] of services) {
458	    if (svc.proc && svc.alive) try { svc.proc.kill('SIGTERM'); } catch {}
459	  }
460	  for (const [, sess] of execSessions) {
461	    if (sess.alive) try { sess.pty.kill(); } catch {}
462	  }
463	  process.exit(0);
464	});
465

