801	export async function killExecSession(
802	  spriteName: string,
803	  sessionId: string,
804	  signal: string = 'SIGTERM',
805	  timeout: string = '5s'
806	): Promise<void> {
807	  const token = await getToken();
808	  const params = new URLSearchParams({ signal, timeout });
809	  const response = await fetch(
810	    `${BASE_URL}/sprites/${encodeURIComponent(spriteName)}/exec/${encodeURIComponent(sessionId)}/kill?${params.toString()}`,
811	    {
812	      method: 'POST',
813	      headers: {
814	        Authorization: `Bearer ${token}`,
815	      },
816	    }
817	  );
818	
819	  if (response.status === 401) throw new AppError('unauthorized', 'Unauthorized');
820	  if (response.status === 404) throw new AppError('notFound', 'Not found');
821	  if (!response.ok) {
822	    const text = await response.text().catch(() => '');
823	    throw new AppError('serverError', text || `Kill error ${response.status}`, response.status);
824	  }
825	
826	  const reader = response.body?.getReader();
827	  if (reader) {
828	    while (true) {
829	      const { done } = await reader.read();
830	      if (done) break;
831	    }
832	  }
833	}
834	
835	// MARK: - Exec Helpers
836	
837	/**
838	 * Run a short command on a sprite via the Exec API.
839	 * Creates a temporary exec session and collects stdout.
840	 * Used for simple operations like waking sprites or fetching session info.
841	 */
842	export async function runExec(
843	  spriteName: string,
844	  command: string,
845	  timeout: number = 15
846	): Promise<{ output: string; success: boolean }> {
847	  let output = '';
848	  let exitCode: number | undefined;
849	  const controller = new AbortController();
850	  const timer = setTimeout(() => controller.abort(), timeout * 1000);
851	
852	  try {
853	    await streamExec(
854	      spriteName,
855	      ['bash', '-c', command],
856	      (event) => {
857	        if (event.type === 'stdout' && event.data) {
858	          output += event.data;
859	        } else if (event.type === 'exit') {
860	          exitCode = event.exit_code ?? 0;
861	        }
862	      },
863	      controller.signal,
864	      {
865	        path: '/bin/bash',
866	        maxRunAfterDisconnect: '1s',
867	      }
868	    );
869	  } catch (err: any) {
870	    if (err.name !== 'AbortError') {
871	      exitCode = exitCode ?? 1;
872	    }
873	  } finally {
874	    clearTimeout(timer);
875	  }
876	
877	  return { output, success: exitCode === 0 };
878	}
