const BASE = '/home/sprite/project/sprites-rn-manager-custom-vm/src/services/aws';
import { signQuery } from `${BASE}/sigv4`;
import * as ec2 from `${BASE}/ec2`;

let failed = false;
function ok(name: string, cond: boolean, detail = '') {
  if (cond) console.log(`ok   ${name}`);
  else { console.error(`FAIL ${name} ${detail}`); failed = true; }
}

const creds = { accessKeyId: 'AKIDEXAMPLE', secretAccessKey: 'wJalrXUtnFEMI/K7MDENG+bPxRfiCYEXAMPLEKEY' };
const now = new Date(Date.UTC(2025, 0, 1, 0, 0, 0));
const region = 'us-east-1';

// --- SigV4 structure + determinism ---
const body = 'Action=DescribeInstances&InstanceId.1=i-0abc&Version=2016-11-15';
const s1 = signQuery({ creds, region, service: 'ec2', host: `ec2.${region}.amazonaws.com`, body, now });
const s2 = signQuery({ creds, region, service: 'ec2', host: `ec2.${region}.amazonaws.com`, body, now });
ok('amz date format', s1.amzDate === '20250101T000000Z', s1.amzDate);
ok('deterministic', s1.headers.Authorization === s2.headers.Authorization);
const auth = s1.headers.Authorization;
ok('cred scope', auth.includes(`Credential=AKIDEXAMPLE/20250101/us-east-1/ec2/aws4_request`), auth);
ok('signed headers', auth.includes('SignedHeaders=content-type;host;x-amz-date'), auth);
ok('signature hex len', /Signature=[0-9a-f]{64}$/.test(auth), auth);

// --- EC2 calls with mocked fetch ---
const realFetch = globalThis.fetch;
let lastReq: { url: string; body: string; headers: any } | null = null;
function mock(xml: string, okStatus = true, status = 200) {
  globalThis.fetch = (async (url: any, init: any) => {
    lastReq = { url: String(url), body: init?.body ?? '', headers: init?.headers ?? {} };
    return { ok: okStatus, status, text: async () => xml } as any;
  }) as any;
}

// RunInstances
mock('<RunInstancesResponse><instancesSet><item><instanceId>i-0abc123</instanceId></item></instancesSet></RunInstancesResponse>');
const run = await ec2.runInstance({ creds, region }, { imageId: 'ami-1', instanceType: 't3.micro', userData: 'Zm9v', name: 'my-vm' });
ok('runInstance parses id', run.instanceId === 'i-0abc123', run.instanceId);
ok('runInstance sends tag', lastReq!.body.includes('ManagedBy') && lastReq!.body.includes('sprites-rn-manager'), lastReq!.body);
ok('runInstance instance type', lastReq!.body.includes('InstanceType=t3.micro'), lastReq!.body);
ok('runInstance endpoint host', lastReq!.url === 'https://ec2.us-east-1.amazonaws.com/', lastReq!.url);

